class Solution:
    def minmaxGasDist(self, stations: list[int], k: int) -> float:
        lo, hi = 0.0, float(stations[-1] - stations[0])
        while hi - lo > 1e-7:
            mid = (lo + hi) / 2.0
            need = 0
            for i in range(len(stations) - 1):
                gap = stations[i + 1] - stations[i]
                q = gap / mid
                need += int(q)
                if abs(q - int(q)) < 1e-12:
                    need -= 1
            if need <= k:
                hi = mid
            else:
                lo = mid
        return round(hi, 6)

